spi = machine.SPI(
    0,
    baudrate=40000000,  # 40MHz for fast, crisp screen updates
    polarity=1,
    phase=1,
    sck=machine.Pin(18),
    mosi=machine.Pin(19)
)

display = st7789.ST7789(
    spi,
    width,                # Width (Portrait)
    height,              # Height (Portrait)
    reset=HARDWARE.rst,
    dc=HARDWARE.dc,
    cs=HARDWARE.cs,
    rotation=0          # 1 = Landscape (90 deg), 0 = Portrait (0 deg)
)

def drawImg(display, filename, x, y, width, height):
    row_bytes = width*2
    try:
        with open(filename, "rb") as f:
            for current_y in range(y, y+height):
                buffer = f.read(row_bytes)
                if not buffer:
                    break
                display.blit_buffer(buffer, x, current_y, width, 1)
    except OSError: 
         print(f"Error: Could not find or read file '{filename}'")

def drawSymbol(display, symbol, x, y):
    mono_fb = framebuf.FrameBuffer(
            symbol["bytearray"],
            symbol["width"],
            symbol["height"],
            framebuf.MONO_HLSB
        )
    
    color_buf = bytearray(symbol["width"] * symbol["height"] * 2)
    color_fb = framebuf.FrameBuffer(color_buf, symbol["width"], symbol["height"], framebuf.RGB565)

    # swapping colours little endian to big
    # 1. Get the normal colors
    raw_bg = st7789.color565(0, 0, 0)
    raw_fg = st7789.color565(29, 185, 84)  # Spotify Green

    # 2. Swap the high byte and low byte so framebuf formats it correctly for SPI
    bg_color = (raw_bg >> 8) | ((raw_bg & 0xFF) << 8)
    fg_color = (raw_fg >> 8) | ((raw_fg & 0xFF) << 8)

    palette_buf = bytearray(4) # 2 pixels * 2 bytes
    palette = framebuf.FrameBuffer(palette_buf, 2, 1, framebuf.RGB565)
    palette.pixel(0, 0, bg_color) # Map all '0' bits to the background color
    palette.pixel(1, 0, fg_color) # Map all '1' bits to the foreground color

    color_fb.blit(mono_fb, 0, 0, -1, palette)
    display.blit_buffer(color_buf, x, y, symbol["width"], symbol["height"])

def drawAlbumCover(display, album, x, y, size):
    if size not in (64, 200):
        raise ValueError("Album cover size must be 64 or 200")

    filename = album["file" + str(size)]
    row_bytes = size * 2

    try:
        with open(filename, "rb") as cover:
            for row in range(size):
                buffer = cover.read(row_bytes)
                if len(buffer) != row_bytes:
                    raise ValueError(
                        "Album cover is incomplete: expected {} bytes per row, got {}".format(
                            row_bytes, len(buffer)
                        )
                    )
                display.blit_buffer(buffer, x, y + row, size, 1)
    except OSError as error:
        raise OSError("Could not open album cover: " + filename) from error

def drawCurrentAlbumCover(display, x, y, size):
    if size not in (64, 200):
        raise ValueError("Album cover size must be 64 or 200")

    response = urequests.get(SERVER + "/getAlbumID")
    try:
        if response.status_code != 200:
            raise RuntimeError("Could not get current album ID: " + response.text)
        album_id = response.json()
    finally:
        response.close()

    response = urequests.get(
        SERVER + "/covers/{}/{}".format(album_id, size)
    )
    row_bytes = size * 2
    try:
        if response.status_code != 200:
            raise RuntimeError("Could not get album cover: " + response.text)

        for row in range(size):
            row_data = response.raw.read(row_bytes)
            if len(row_data) != row_bytes:
                raise RuntimeError("Album cover stream ended before all rows arrived")
            display.blit_buffer(row_data, x, y + row, size, 1)
    finally:
        response.close()

def drawCurrentAlbumCover2(display, x, y):
    source_size = 64
    target_size = 200
    source_row_bytes = source_size * 2
    target_row_bytes = target_size * 2

    response = urequests.get(SERVER + "/getAlbumID")
    try:
        if response.status_code != 200:
            raise RuntimeError("Could not get current album ID: " + response.text)
        album_id = response.json()
    finally:
        response.close()

    response = urequests.get(
        SERVER + "/covers/{}/{}".format(album_id, source_size)
    )
    try:
        if response.status_code != 200:
            raise RuntimeError("Could not get album cover: " + response.text)

        source_row_index = -1
        source_row = bytearray(source_row_bytes)
        for target_y in range(target_size):
            wanted_source_row = target_y * source_size // target_size
            while source_row_index < wanted_source_row:
                source_row_data = bytearray()
                while len(source_row_data) < source_row_bytes:
                    chunk = response.raw.read(source_row_bytes - len(source_row_data))
                    if not chunk:
                        raise RuntimeError("64x64 cover stream ended before all rows arrived")
                    source_row_data.extend(chunk)
                source_row = source_row_data
                source_row_index += 1

            scaled_row = bytearray(target_row_bytes)
            for target_x in range(target_size):
                source_x = target_x * source_size // target_size
                source_offset = source_x * 2
                target_offset = target_x * 2
                scaled_row[target_offset] = source_row[source_offset]
                scaled_row[target_offset + 1] = source_row[source_offset + 1]

            display.blit_buffer(scaled_row, x, y + target_y, target_size, 1)
    finally:
        response.close()

def hideSymbol(display, symbol, x, y):
    width = symbol["width"]
    height = symbol["height"]
    black = st7789.color565(0, 0, 0)
    color_buf = bytearray(width * height * 2)

    for index in range(0, len(color_buf), 2):
        color_buf[index] = black >> 8
        color_buf[index + 1] = black & 0xFF

    display.blit_buffer(color_buf, x, y, width, height)
    
